"""Generated by eglot-python-preset."""

import os
import re
import sys
from importlib.metadata import version
from typing import Any, cast

from rassumfrassum.frassum import LspLogic, Server
from rassumfrassum.json import JSON
from rassumfrassum.util import dmerge

SERVERS: list[list[str]] = __SERVERS__  # type: ignore[name-defined]
TY_CONFIGURATION: dict[str, Any] | None = __TY_CONFIGURATION__  # type: ignore[name-defined]
BASEDPYRIGHT_CONFIGURATION: dict[str, Any] | None = __BASEDPYRIGHT_CONFIGURATION__  # type: ignore[name-defined]
PYREFLY_CONFIGURATION: dict[str, Any] | None = __PYREFLY_CONFIGURATION__  # type: ignore[name-defined]


MIN_RASS_VERSION = (0, 3, 5)


def _warn_if_rass_too_old() -> None:
    """Warn on stderr, which Eglot logs, when rass predates MIN_RASS_VERSION."""
    try:
        installed = version("rassumfrassum")
        parts = tuple(int(part) for part in installed.split(".")[:3])
    except Exception:
        return
    if parts < MIN_RASS_VERSION:
        wanted = ".".join(str(part) for part in MIN_RASS_VERSION)
        print(
            f"eglot-python-preset: rassumfrassum {installed} is older than "
            f"{wanted}, so per-server settings will not apply; "
            "please upgrade it",
            file=sys.stderr,
        )


def _utf16_len(text: str) -> int:
    return len(text) + sum(1 for char in text if ord(char) > 0xFFFF)


def _lsp_position_of(text: str, index: int) -> dict[str, int]:
    line_start = text.rfind("\n", 0, index) + 1
    return {
        "line": text.count("\n", 0, index),
        "character": _utf16_len(text[line_start:index]),
    }


def _diff_changes(old: str, new: str) -> list[dict[str, Any]]:
    """Return one ranged contentChange that turns OLD into NEW.

    Replaces rass 0.3.5's version, which splits lines with
    ``str.splitlines`` (so form feeds and other separators shift the
    edit to the wrong line) and diffs in roughly quadratic time.  Lines
    here end only at newlines, as in Eglot and rass's _lsp_position.
    """
    if old == new:
        return []
    limit = min(len(old), len(new))
    prefix = 0
    while prefix < limit and old[prefix] == new[prefix]:
        prefix += 1
    suffix = 0
    while suffix < limit - prefix and old[-1 - suffix] == new[-1 - suffix]:
        suffix += 1
    return [
        {
            "range": {
                "start": _lsp_position_of(old, prefix),
                "end": _lsp_position_of(old, len(old) - suffix),
            },
            "text": new[prefix : len(new) - suffix],
        }
    ]


def _install_diff_changes_fix() -> None:
    """Use _diff_changes when rass translates full-text changes."""
    import rassumfrassum.frassum as frassum_module

    if hasattr(frassum_module, "_diff_changes"):
        frassum_module._diff_changes = _diff_changes


_warn_if_rass_too_old()
_install_diff_changes_fix()


def _server_kind(name: str) -> str | None:
    base = name.lower().split("#", 1)[0]
    if "." in base:
        base = base.rsplit(".", 1)[0]
    if base in ("basedpyright", "basedpyright-langserver"):
        return "basedpyright"
    if base == "pyrefly":
        return "pyrefly"
    if base == "ruff":
        return "ruff"
    if base == "ty":
        return "ty"
    return None


def _rass_server_pattern(index: int) -> str:
    """Return a regex matching the name rass gives server INDEX at launch."""
    base = os.path.basename(SERVERS[index][0])
    name = f"{base}#{index}" if index else base
    return f"^{re.escape(name)}$"


def _initialize_overlays() -> dict[str, dict[str, Any]]:
    """Return per-server initializationOptions keyed by rass name pattern."""
    overlays: dict[str, dict[str, Any]] = {}
    for index, command in enumerate(SERVERS):
        kind = _server_kind(os.path.basename(command[0]))
        if kind == "ty" and TY_CONFIGURATION:
            overlays[_rass_server_pattern(index)] = TY_CONFIGURATION
        elif kind == "pyrefly" and PYREFLY_CONFIGURATION:
            overlays[_rass_server_pattern(index)] = PYREFLY_CONFIGURATION
    return overlays


def _merge_response_items(
    request_params: JSON,
    response_payload: JSON,
    sections: tuple[str, ...],
    override: dict[str, Any],
) -> None:
    if not isinstance(response_payload, list):
        return
    req_items = cast(list[dict[str, Any]], request_params.get("items", []))
    if len(response_payload) < len(req_items):
        response_payload.extend([None] * (len(req_items) - len(response_payload)))
    for i, item in enumerate(req_items):
        if item.get("section", "") in sections:
            existing = response_payload[i]
            if isinstance(existing, dict):
                response_payload[i] = dmerge(existing, override)
            else:
                response_payload[i] = dmerge({}, override)


class GeneratedPythonLogic(LspLogic):
    async def on_client_request(
        self, method: str, params: JSON, servers: list[Server]
    ):
        # rass applies the "rass" key per server and strips it before
        # forwarding, so each overlay reaches only the server it names.
        if method == "initialize" and (overlays := _initialize_overlays()):
            init_opts = params.get("initializationOptions") or {}
            params["initializationOptions"] = {
                **init_opts,
                "rass": {**overlays, **(init_opts.get("rass") or {})},
            }
        return await super().on_client_request(method, params, servers)

    async def on_client_response(
        self,
        method: str,
        request_params: JSON,
        response_payload: JSON,
        is_error: bool,
        server: Server,
    ) -> None:
        if method == "workspace/configuration" and not is_error:
            kind = _server_kind(server.name)
            if kind == "basedpyright" and BASEDPYRIGHT_CONFIGURATION:
                _merge_response_items(
                    request_params,
                    response_payload,
                    ("", "python"),
                    BASEDPYRIGHT_CONFIGURATION,
                )
            elif kind == "ty" and TY_CONFIGURATION:
                _merge_response_items(
                    request_params,
                    response_payload,
                    ("", "ty"),
                    TY_CONFIGURATION,
                )
        await super().on_client_response(
            method,
            request_params,
            response_payload,
            is_error,
            server,
        )


def servers():
    return SERVERS


def logic_class():
    return GeneratedPythonLogic
